DROP TABLE IF EXISTS `t_commande`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_commande` (
  `commande_id` int NOT NULL AUTO_INCREMENT,
  `date_creation` datetime DEFAULT NULL,
  `type` varchar(25) DEFAULT NULL,
  `statut` varchar(25) DEFAULT NULL,
  `adresse_livraison_fk` int DEFAULT NULL,
  `client_fk` int NOT NULL,
  PRIMARY KEY (`commande_id`),
  KEY `adresse_livraison_fk` (`adresse_livraison_fk`),
  KEY `client_fk` (`client_fk`),
  CONSTRAINT `t_commande_ibfk_1` FOREIGN KEY (`adresse_livraison_fk`) REFERENCES `t_address` (`address_id`),
  CONSTRAINT `t_commande_ibfk_2` FOREIGN KEY (`client_fk`) REFERENCES `t_client` (`client_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
